// @pit: {"label": "Close issues 402 and 409 with explanatory comments"}
async ({ shell: { execFile } }) => {
  const run = (args: string[]) => execFile("gh", args, { raise: true }).then(r => (r.stdout + r.stderr).trim());
  const c402 = await run(["issue", "close", "402", "--repo", "cv/pit", "--reason", "completed", "--comment",
    "Superseded by [v0.39.0](https://github.com/cv/pit/releases/tag/v0.39.0), which includes everything planned for v0.38.1. v0.38.1 was never tagged."]);
  const c409 = await run(["issue", "close", "409", "--repo", "cv/pit", "--reason", "completed", "--comment",
    "Fixed by #410, released in [v0.39.0](https://github.com/cv/pit/releases/tag/v0.39.0). Tested live by @cv on a local install. pi-durable (`src/durable/`, including its `[Pit: collapsed …]` format) is out of scope for now; we'll add the check there if the problem shows up in pi-durable sessions."]);
  const states = await run(["issue", "list", "--repo", "cv/pit", "--state", "all", "--search", "402 OR 409 in:number", "--json", "number,state", "--limit", "5"]).catch(() => "");
  const [s402, s409] = await Promise.all(["402", "409"].map(n => run(["issue", "view", n, "--repo", "cv/pit", "--json", "number,state,stateReason"])));
  return { c402, c409, s402, s409 };
}
